-- ShootRadar pilot: event list. Run after schema.sql. Safe to run again: it refreshes these events.
on conflict (id) do update set name = excluded.name, cat = excluded.cat, city = excluded.city, venue = excluded.venue, area = excluded.area, address = excluded.address, starts_at = excluded.starts_at, ends_at = excluded.ends_at, end_est = excluded.end_est, days = excluded.days, daily = excluded.daily, doors = excluded.doors, show = excluded.show, time_note = excluded.time_note, crowd = excluded.crowd, ticket = excluded.ticket, source = excluded.source, organiser = excluded.organiser, status = excluded.status, access = excluded.access, access_note = excluded.access_note, tags = excluded.tags, f = excluded.f, outdoor = excluded.outdoor, minors = excluded.minors, tips = excluded.tips;
